import type { Coupon } from '../subscription/interface';
import type { CouponConfigMetadata } from './interface';

/**
 * Checks if user selected a similar coupon to what is configured in the coupon config.
 * This is helpful, for example, to check if user entered a CS version of the coupon.
 */
export function hasAlikeCoupon(couponConfig: CouponConfigMetadata | undefined, coupon: Coupon | undefined) {
    if (!couponConfig || !coupon?.Code) {
        return false;
    }

    const coupons = Array.isArray(couponConfig.coupons) ? couponConfig.coupons : [couponConfig.coupons];

    return coupons.some((couponStr) => coupon.Code.startsWith(couponStr));
}

export function isCSCoupon(coupon: Coupon | string | undefined) {
    if (!coupon) {
        return false;
    }

    const couponStr = typeof coupon === 'string' ? coupon : coupon.Code;

    return couponStr.endsWith('CS');
}
